  0% {
    opacity: 0;
    transform: translate(-50%, -50%) rotate(0) scale(0.3);
  }
  18% {
    opacity: 1;
  }
  68% {
    opacity: 1;
    transform: translate(calc(-50% + var(--kida-sticker-x)), calc(-50% + var(--kida-sticker-y)))
